rep = json.loads(Path("benchmark/work/_match_report.json").read_text(encoding="utf-8"))
ids = [it["legacy_id"] for it in rep["items"]]
missing = [i for i in ids if i not in D]
extra = [i for i in D if i not in ids]
if missing or extra:
    raise SystemExit(f"missing={missing} extra={extra}")

out = []
for it in rep["items"]:
    decision, status, reason, notes = D[it["legacy_id"]]
    ev = []
    for m in it["markers"]:
        if m.get("kind") != "substantive":
            continue
        w = m.get("window") or {}
        ev.append({
            "marker": m.get("text"),
            "document_id": w.get("doc_id"),
            "article": w.get("article"),
            "clause": w.get("clause"),
            "point": w.get("point"),
            "snippet": (w.get("snippet") or "")[:400],
        })
    out.append({
        "legacy_id": it["legacy_id"],
        "nhom": it["nhom"],
        "decision": decision,
        "reason": reason,
        "source_checked": True,
        "verification_status": status,
        "notes": notes,
        "question": it["question"],
        "answers": it["answers"],
        "document_ids": it.get("source_doc_ids") or [],
        "cited_articles": it.get("cited_articles") or [],
        "matcher_flags": it.get("flags") or [],
        "evidence_note": "snippet là cửa sổ matcher để đối chiếu, không phải câu gold đã chốt và không đối công báo.",
        "evidence": ev,
    })

path = Path("benchmark/work/legacy_audit.json")
path.write_text(json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8")
from collections import Counter
c = Counter(r["decision"] for r in out)
v = Counter(r["verification_status"] for r in out)
print("n", len(out), dict(c), dict(v))
print("DROP", [r["legacy_id"] for r in out if r["decision"]=="DROP"])
